    "stem": "以下关于区块链的说法中，错误的是()。",
    "options": {
      "A": "区块链分为公有链、联盟链、私有链和混合链四大类",
      "B": "区块链概念可以理解为以非对称加密算法为基础，以改进的默克尔树为数据结构，使用共识机制、点对点 网络、智能合约等技术结合而成的一种分布式存储数据库技术",
      "C": "激励机制可确保分布式系统中的所有节点均可参与数据区块的验证过程，并通过共识机制选择特定节点将 新产生的区块加入到区块链中",
      "D": "区块链系统中的加密算法一般分为散列(哈希)算法和对称加密算法"
    },
    "answer": "D",
    "explanation": "P59, 区块链的关键技术：分布式账本、加密算法、共识机制。 分布式账本 分布式账本是区块链技术的核心之一。 每一个节点保存一个唯一、真实账本的副本阿牛，理论上除非所有的节点被破坏，所有整 个分布式账本系统是非常稳健的，从而保证了账目数据的安全性。 加密算法 区块链系统中的加密算法一般分为散列(哈希)算法和非对称加密算法。 散列算法也叫数据摘要或者哈希算法也被理解为该数据的“指纹信息”。典型的散列算法有 MD5、SHA- 1/SHA-2和SM3,目前区块链主要使用SHA-2中的SHA256算法。 常用的非对称加密算法包括RSA、Elgamal、D-H、ECC(椭圆曲线加密算法)等。 【蜗牛老师点评】散列算法不可逆，主要是为了进行数据检验，防止数据被篡改，当然也 会被用作加密功能。加密算法可逆，主要用作数据保密功能。 共识机制 在互联网世界，共识主要是计算机和软件程序协作一致的基本保障，是分布式系统节点或 程序运行的基本依据。 区块链的共识机制的思想是：在没有中心点总体协调的情况下，当某个记账节点提议区块 数据增加或减少，并把该提议广播给所有的参与节点，所有节点要根据一定的规则和机制， 对这一提议是否能够达成一致进行计算和处理。 目前，常用的共识机制主要有PoW、PoS、DPoS、Paxos、PBFT等。 共识机制分析可基于：合规监管、性能效率、资源消耗、容错性。"
