    "explanation": "按照云计算服务提供的资源层次，可以分为IaaS 、PaaS 和 SaaS 三种服务类型。 IaaS (基础设施即服务),向用户提供计算机能力、存储空间等基础设施方面的服务。IaaS 服务单纯出租资源， 盈利能力有限。【仅仅提供了一个场所】 PaaS (平台即服务),向用户提供虚拟的操作系统、数据库管理系统、Web 应用等平台化的服务。PaaS 服务 的重点不在于直接的经济效益，而更注重构建和形成紧密的产业生态。【不光提供了场所，还提供了配套的 生产设备】 SaaS (软件即服务),向用户提供应用软件(如 CRM 、办公软件等)、组件、工作流等虚拟化软件的服务，SaaS 向用户提供多租户、可定制的应用能力，使软件提供商从软件产品的生产者转变为应用服务的运营者。【直 接提供做好了的产品给你】"
