    "explanation": "表5-11存储管理的主要内容 管理 主要内容 资源调度管理 资源调度管理的功能主要是添加或删除存储节点，编辑存储节点的信息，设定某类型存储 资源属于某个节点，或者设定这些资源比较均衡地存储到节点上。它包含存储控制、拓扑 配置以及各种网络设备如集线器、交换机、路由器和网桥等的故障隔离 存储资源管理 存储资源管理是一类应用程序，它们管理和监控物理和逻辑层次上的存储资源，从而简化 资源管理，提高数据的可用性。被管理的资源包括存储硬件如RAID、磁带以及光盘库。存 储资源管理不仅包括监控存储系统的状况、可用性、性能以及配置情况，还包括容量和配 置管理以及事件报警等，从而提供优化策略 负载均衡管理 负载均衡是为了避免存储资源由于资源类型、服务器访问频率和时间不均衡造成浪费或形 成系统瓶颈而平衡负载的技术 安全管理 存储系统的安全主要是防止恶意用户攻击系统或窃取数据。系统攻击大致分为两类：一类 以扰乱服务器正常工作为目的，如拒绝服务攻击DoS等；另一类以入侵或破坏服务器为目 的，如窃取数据、修改网页等"
