    "answer": "A",
    "explanation": "《蜗牛软考综合一本通》--5.4.2 安全系统★★★★★ 安全机制包含基础设施实体安全、平台安全、数据安全、通信安全、应用安全、运行安全、管理安全、授权 和审计安全、安全防范体系等。 *(1)基础设施实体安全。基础设施实体安全主要包括机房安全、场地安全、设施安全、动力系统安全、灾难预 防与恢复等。 *(2)平台安全。平台安全主要包括操作系统漏洞检测与修复、网络基础设施漏洞检测与修复、通用基础应用程 序漏洞检测与修复、网络安全产品部署等。 *(3)数据安全。数据安全主要包括介质与载体安全保护、数据访问控制、数据完整性、数据可用性、数据监控 和审计、数据存储与备份安全等。 *(4)通信安全。通信主要包括通信线路和网络基础设施安全性测试与优化、安装网络加密设施、设置通信加密 软件、设置身份鉴别机制、设置并测试安全通道、测试各项网络协议运行漏洞等。 *(5)应用安全。应用安全主要包括业务软件的程序安全性测试(Bug 分析)、业务交往的防抵赖测试、业务资源 的访问控制验证测试、业务实体的身份鉴别检测、业务现场的备份与恢复机制检查，以及业务数据的唯一性 与一致性及防冲突检测、业务数据的保密性测试、业务系统的可靠性测试、业务系统的可用性测试等。 *(6)运行安全。运行安全主要包括应急处置机制和配套服务、网络系统安全性监测、网络安全产品运行监测、 定期检查和评估、系统升级和补丁提供、跟踪最新安全漏洞及通报、灾难恢复机制与预防、系统改造管理、 网络安全专业技术咨询服务等。 *(7)管理安全。管理安全主要包括人员管理、培训管理、应用系统管理、软件管理、设备管理、文档管理、数 据管理、操作管理、运行管理、机房管理等。 *(8)授权和审计安全。授权安全是指以向用户和应用程序提供权限管理和授权服务为目标，主要负责向业务应 用系统提供授权服务管理，提供用户身份到应用授权的映射功能，实现与实际应用处理模式相对应的，与具 体应用系统开发和管理无关的访问控制机制。 *(9)安全防范体系。组织安全防范体系的建立，就是使得组织具有较强的应急事件处理能力，其核心是实现组 织信息安全资源的综合管理。"
