    "explanation": "对应用集成的技术要求大致有： *(1)具有应用间的互操作性：应用的互操作性提供不同系统间信息的有意义交换，即信息的语用交换，而 不仅限于语法交换和语义交换。此外，它还提供系统间功能服务的使用功能，特别是资源的动态发现和动态 类型检查。 *(2)具有分布式环境中应用的可移植性：提供应用程序在系统中迁移的潜力并且不破坏应用所提供的或正 在使用的服务。这种迁移包括静态的系统重构或重新安装以及动态的系统重构。 *(3)具有系统中应用分布的透明性：分布的透明性屏蔽了由系统的分布所带来的复杂性。它使应用编程者 不必关心系统是分布的还是集中的，从而可以集中精力设计具体的应用系统，这就大大减少了应用集成编程 的复杂性。"
